15	package typeinfo
16	
17	import (
18		"fmt"
19	
20		"github.com/dolthub/go-mysql-server/sql"
21	
22		"github.com/dolthub/dolt/go/store/types"
23		"github.com/dolthub/dolt/go/store/val"
24	)
