351	func deserializeColumns(ctx context.Context, s *serial.TableSchema) ([]schema.Column, error) {
352		length := s.ColumnsLength()
353		isKeyless, err := keylessSerialSchema(s)
354		if err != nil {
355			return nil, err
356		}
357		if isKeyless {
358			// (6/15/22)
359			// currently, keyless id and cardinality columns
360			// do not exist in schema.Schema
361			// we do serialize them in the flatbuffer
362			// message, in order to describe index storage.
363			// by convention, they are stored as the last
364			// two columns in the columns vector.
365			length -= 2
366		}
367	
368		cols := make([]schema.Column, length)
369		c := serial.Column{}
370		for i := range cols {
371			_, err := s.TryColumns(&c, i)
372			if err != nil {
373				return nil, err
