package typeinfo

// PreserveAdaptiveEncoding returns the fresh TypeInfo with its storage encoding pinned to the
// existing TypeInfo's encoding, when both represent the same type family. This prevents a
// freshly-constructed TypeInfo from silently adopting the global adaptive-encoding default
// (see UseAdaptiveEncoding) when the column was originally persisted under a legacy address
// encoding.
//
// It acts as a no-op (returning fresh unchanged) when:
//   - existing is nil,
//   - the two TypeInfos belong to different type families (e.g. VARCHAR to TEXT, or Point to
//     LineString), or
//   - the type family does not use variable adaptive encoding (e.g. integer types).
//
// When fresh is nil, it returns nil.
//
// The covered type families are string/text (blobStringType), binary/blob (varBinaryType),
// JSON (jsonType), and all concrete geometry types (pointType, linestringType, polygonType,
// multipointType, multilinestringType, multipolygonType, geomcollType, geometryType). The SQL
// type semantics of fresh (such as a text column's maximum length) are preserved; only the
// storage encoding is carried over from existing.
func PreserveAdaptiveEncoding(existing TypeInfo, fresh TypeInfo) TypeInfo {
	if fresh == nil {
		return nil
	}
	if existing == nil {
		return fresh
	}

	// Only preserve the encoding when existing and fresh belong to the same type family and that
	// family uses variable adaptive encoding. sameAdaptiveFamily reports whether the two TypeInfos
	// are the same concrete adaptive-encoding type.
	if !sameAdaptiveFamily(existing, fresh) {
		return fresh
	}

	return fresh.WithEncoding(existing.Encoding())
}

// sameAdaptiveFamily reports whether existing and fresh are the same concrete TypeInfo type and
// that type belongs to a family that uses variable adaptive encoding.
func sameAdaptiveFamily(existing TypeInfo, fresh TypeInfo) bool {
	switch fresh.(type) {
	case *blobStringType:
		_, ok := existing.(*blobStringType)
		return ok
	case *varBinaryType:
		_, ok := existing.(*varBinaryType)
		return ok
	case *jsonType:
		_, ok := existing.(*jsonType)
		return ok
	case *pointType:
		_, ok := existing.(*pointType)
		return ok
	case *linestringType:
		_, ok := existing.(*linestringType)
		return ok
	case *polygonType:
		_, ok := existing.(*polygonType)
		return ok
	case *multipointType:
		_, ok := existing.(*multipointType)
		return ok
	case *multilinestringType:
		_, ok := existing.(*multilinestringType)
		return ok
	case *multipolygonType:
		_, ok := existing.(*multipolygonType)
		return ok
	case *geomcollType:
		_, ok := existing.(*geomcollType)
		return ok
	case *geometryType:
		_, ok := existing.(*geometryType)
		return ok
	default:
		return false
	}
}
