194	func replaceColumnInSchema(sch schema.Schema, oldCol schema.Column, newCol schema.Column, order *sql.ColumnOrder) (schema.Schema, error) {
195		// If no order is specified, insert in the same place as the existing column
196		prevColumn := ""
197		for _, col := range sch.GetAllCols().GetColumns() {
198			if col.Name == oldCol.Name {
199				if prevColumn == "" {
200					if order == nil {
201						order = &sql.ColumnOrder{First: true}
202					}
203				}
204				break
205			} else {
206				prevColumn = col.Name
207			}
208		}
209	
210		if order == nil {
211			if prevColumn != "" {
212				order = &sql.ColumnOrder{AfterColumn: prevColumn}
213			} else {
214				return nil, fmt.Errorf("Couldn't find column %s", oldCol.Name)
215			}
216		}
217	
218		var newCols []schema.Column
219		if order.First {
220			newCols = append(newCols, newCol)
221		}
222	
223		for _, col := range sch.GetAllCols().GetColumns() {
224			if col.Name != oldCol.Name {
225				newCols = append(newCols, col)
226			}
227	
228			if order.AfterColumn == col.Name {
229				newCols = append(newCols, newCol)
230			}
231		}
232	
233		collection := schema.NewColCollection(newCols...)
234	
235		err := schema.ValidateForInsert(collection)
236		if err != nil {
237			return nil, err
238		}
239	
240		newSch, err := schema.SchemaFromCols(collection)
241		if err != nil {
242			return nil, err
243		}
244		for _, index := range sch.Indexes().AllIndexes() {
245			tags := index.IndexedColumnTags()
246			for i := range tags {
247				if tags[i] == oldCol.Tag {
248					tags[i] = newCol.Tag
249				}
250			}
251			_, err = newSch.Indexes().AddIndexByColTags(
252				index.Name(),
253				tags,
254				index.PrefixLengths(),
255				schema.IndexProperties{
256					IsUnique:           index.IsUnique(),
257					IsSpatial:          index.IsSpatial(),
258					IsFullText:         index.IsFullText(),
259					IsVector:           index.IsVector(),
260					IsUserDefined:      index.IsUserDefined(),
261					Comment:            index.Comment(),
262					Predicate:          index.Predicate(),
263					FullTextProperties: index.FullTextProperties(),
264					VectorProperties:   index.VectorProperties(),
265				})
266			if err != nil {
267				return nil, err
268			}
269		}
270	
271		// Copy over all checks from the old schema
272		for _, check := range sch.Checks().AllChecks() {
273			_, err := newSch.Checks().AddCheck(check.Name(), check.Expression(), check.Enforced())
274			if err != nil {
275				return nil, err
276			}
277		}
278	
279		// Copy over the collation
280		newSch.SetCollation(sch.GetCollation())
281	
282		// Copy over target row size
283		newSch.SetTargetRowSize(sch.GetTargetRowSize())
284	
285		pkOrds, err := modifyPkOrdinals(sch, newSch)
286		if err != nil {
287			return nil, err
288		}
289		err = newSch.SetPkOrdinals(pkOrds)
290		if err != nil {
291			return nil, err
292		}
293		return newSch, nil
294	}
